    def recurse_print(_s):
        if _s.count('(') == _s.count(')'):
            for __ in _s:
                print(f' {" " if __ == ')' else " " * len(__) if __ == '(' else __} ')
        elif _s.count('(') > _s.count(')'):
            print(' ' * len(__), end="")
            recurse_print(_s.replace('(', ' ( ', 1))
            print('')
        else:
