def get_fib_number(index: int, previous: float, current: float) -> int:
    """ Get the index Fibonacci number, where index >= 0.
    >>> get_fib_number(0, 0, 1)
    0
    >>> get_fib_number(1, 0, 1)
    1
    >>> get_fib_number(2, 0, 1)
    1
    >>> get_fib_number(3, 0, 1)
    2
    >>> get_fib_number(12, 0, 1)
    144
    """
    if index == 0:
        return 0
    elif index == 1:
        return 1
    elif index == 2:
        return 1
    elif index > 2:
        return get_fib_number(index-1, current, current + previous)

