    groups = []
    while len(paren_string):
        group = ""
        while len(paren_string):
            cur = paren_string[0]
            if cur == "(":
                paren_string = paren_string[1:]
                group = group + cur
                continue
            if cur == ")":
                paren_string = paren_string[1:]
                if group and not len(paren_string):
                    groups.append(group)
                return groups
            if not len(paren_string) and group == "":
                return groups

